<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Ye Olde Bow &amp; Balloons — Level 1</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&display=swap" rel="stylesheet" />
  <style>
    :root {
      --win-bg: #c0c0c0;
      --win-light: #ffffff;
      --win-dark: #808080;
      --win-darker: #000000;
      --win-blue: #000080;
      --win-blue-light: #1084d0;
    }

    * {
      box-sizing: border-box;
      user-select: none;
      -webkit-user-select: none;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: #008080;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: 'VT323', monospace;
      padding: 12px;
    }

    .win95-window {
      background: var(--win-bg);
      border-top: 2px solid var(--win-light);
      border-left: 2px solid var(--win-light);
      border-right: 2px solid var(--win-darker);
      border-bottom: 2px solid var(--win-darker);
      box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.35);
      padding: 3px;
      width: min(860px, 100%);
    }

    .title-bar {
      background: linear-gradient(90deg, var(--win-blue), var(--win-blue-light));
      color: #fff;
      padding: 4px 8px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-family: 'Press Start 2P', monospace;
      font-size: 11px;
      letter-spacing: 0.5px;
    }

    .title-controls {
      display: flex;
      gap: 4px;
    }

    .win-btn {
      background: var(--win-bg);
      border-top: 2px solid var(--win-light);
      border-left: 2px solid var(--win-light);
      border-right: 2px solid var(--win-darker);
      border-bottom: 2px solid var(--win-darker);
      color: #000;
      font-family: 'Press Start 2P', monospace;
      font-size: 9px;
      padding: 3px 7px;
      cursor: pointer;
    }

    .win-btn:active {
      border-top: 2px solid var(--win-darker);
      border-left: 2px solid var(--win-darker);
      border-right: 2px solid var(--win-light);
      border-bottom: 2px solid var(--win-light);
      transform: translate(1px, 1px);
    }

    .hud-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      padding: 6px 8px;
      background: var(--win-bg);
      border-bottom: 2px solid var(--win-dark);
      font-family: 'Press Start 2P', monospace;
      font-size: 11px;
      flex-wrap: wrap;
    }

    .hud-panel {
      background: #000;
      color: #00ff66;
      padding: 4px 10px;
      border-top: 2px solid var(--win-dark);
      border-left: 2px solid var(--win-dark);
      border-right: 2px solid var(--win-light);
      border-bottom: 2px solid var(--win-light);
      min-width: 110px;
    }

    .hud-hearts {
      color: #ff3b5c;
      letter-spacing: 3px;
    }

    .canvas-wrap {
      position: relative;
      background: #000;
      border-top: 2px solid var(--win-dark);
      border-left: 2px solid var(--win-dark);
      border-right: 2px solid var(--win-light);
      border-bottom: 2px solid var(--win-light);
      overflow: hidden;
    }

    canvas {
      display: block;
      width: 100%;
      height: auto;
      aspect-ratio: 800 / 500;
      cursor: crosshair;
      image-rendering: pixelated;
    }

    .overlay {
      position: absolute;
      inset: 0;
      background: rgba(0, 0, 0, 0.55);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 16px;
    }

    .overlay.hidden {
      display: none;
